### 🧠 Smart Contract: `VestingTokenDistributor.sol`

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";

contract VestingTokenDistributor is
    Initializable,
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable
{
    struct VestingSchedule {
        uint256 start;
        uint256 cliff;
        uint256 duration;
        uint256 totalAmount;
        uint256 released;
        bool revocable;
    }

    IERC20Upgradeable public token;
    mapping(address => VestingSchedule) public vestingSchedules;
    mapping(address => bool) public revoked;

    event TokensVested(address indexed beneficiary, uint256 amount);
    event VestingScheduleCreated(address indexed beneficiary, uint256 amount);
    event VestingRevoked(address indexed beneficiary);

    function initialize(IERC20Upgradeable _token) public initializer {
        __Ownable_init();
        __ReentrancyGuard_init();
        token = _token;
    }

    function createVestingSchedule(
        address beneficiary,
        uint256 amount,
        uint256 start,
        uint256 cliff,
        uint256 duration,
        bool revocable
    ) external onlyOwner {
        require(beneficiary != address(0), "Invalid beneficiary");
        require(amount > 0, "Amount must be > 0");
        require(start >= block.timestamp, "Start must be in the future");
        require(cliff <= duration, "Cliff must be <= duration");

        VestingSchedule storage schedule = vestingSchedules[beneficiary];
        require(schedule.totalAmount == 0, "Vesting already exists");

        schedule.start = start;
        schedule.cliff = cliff;
        schedule.duration = duration;
        schedule.totalAmount = amount;
        schedule.revocable = revocable;

        require(token.transferFrom(owner(), address(this), amount), "Transfer failed");

        emit VestingScheduleCreated(beneficiary, amount);
    }

    function revokeVesting(address beneficiary) external onlyOwner {
        VestingSchedule storage schedule = vestingSchedules[beneficiary];
        require(schedule.revocable, "Vesting is not revocable");
        require(!revoked[beneficiary], "Already revoked");

        revoked[beneficiary] = true;
        uint256 unreleased = schedule.totalAmount - schedule.released;
        if (unreleased > 0) {
            token.transfer(owner(), unreleased);
        }

        emit VestingRevoked(beneficiary);
    }

    function releaseTokens() external nonReentrant {
        VestingSchedule storage schedule = vestingSchedules[msg.sender];
        require(schedule.totalAmount > 0, "No vesting schedule");
        require(!revoked[msg.sender], "Vesting revoked");

        uint256 currentTime = block.timestamp;
        require(currentTime >= schedule.start, "Vesting not started");

        uint256 vestedAmount = _vestedAmount(msg.sender, currentTime);
        uint256 releasableAmount = vestedAmount - schedule.released;

        require(releasableAmount > 0, "No tokens to release");

        schedule.released += releasableAmount;
        token.transfer(msg.sender, releasableAmount);

        emit TokensVested(msg.sender, releasableAmount);
    }

    function _vestedAmount(address beneficiary, uint256 time) internal view returns (uint256) {
        VestingSchedule memory schedule = vestingSchedules[beneficiary];
        if (revoked[beneficiary]) return schedule.released;

        if (time < schedule.start) return 0;
        if (time < schedule.start + schedule.cliff) return 0;

        uint256 totalVestingTime = schedule.start + schedule.duration;
        if (time >= totalVestingTime) return schedule.totalAmount;

        return (schedule.totalAmount * (time - schedule.start)) / schedule.duration;
    }

